<script setup>
import {ref,onMounted,watch} from 'vue'
import {ElMessage} from 'element-plus'
import {api,notifyError} from '../lib/api.js'
import {currentMonth,money,moneyRule,budgetText,pct} from '../lib/format.js'
import StateBox from '../components/StateBox.vue'
import AppIcon from '../components/AppIcon.vue'
const month=ref(currentMonth()),budget=ref(null),loading=ref(false),error=ref(''),dialog=ref(false),busy=ref(false),form=ref({amount:''}),formRef=ref();let serial=0
async function load(){if(!month.value)return;const n=++serial;loading.value=true;error.value='';try{const b=await api.get(`/budgets/${month.value}`);if(n===serial)budget.value=b}catch(e){if(n===serial)error.value=e.message}finally{if(n===serial)loading.value=false}}
function open(){form.value.amount=budget.value?.amount?String(budget.value.amount):'';dialog.value=true;formRef.value?.clearValidate()}
async function save(){if(busy.value||!await formRef.value.validate().catch(()=>false))return;busy.value=true;try{await api.put(`/budgets/${month.value}`,{amount:form.value.amount.trim()});ElMessage.success('月度预算已保存');dialog.value=false;await load()}catch(e){notifyError(e)}finally{busy.value=false}}
onMounted(load);watch(month,load)
</script><template><div class="view-toolbar"><span class="eyebrow">MONTHLY PLAN</span><el-date-picker v-model="month" type="month" value-format="YYYY-MM" :clearable="false" aria-label="预算月份"/></div><StateBox :error="error" @retry="load"><section v-loading="loading" class="panel budget-main" v-if="budget"><div class="panel-heading"><div><h2>{{month}} 月度预算</h2><p>{{budget.status==='NOT_SET'?'先给这个月定个计划，再一步步靠近。':'预算会根据当月支出自动更新。'}}</p></div><el-button type="primary" @click="open">{{budget.status==='NOT_SET'?'设置预算':'调整预算'}}</el-button></div><template v-if="budget.status!=='NOT_SET'"><div class="budget-hero"><div><span class="muted">本月已经花费</span><h2>{{money(budget.spent)}}</h2><p>预算 {{money(budget.amount)}}</p></div><span class="budget-percent" :class="{danger:budget.status==='EXCEEDED'}">{{budget.usageRate}}<small>%</small></span></div><el-progress :percentage="pct(budget.usageRate)" :show-text="false" :stroke-width="14" :color="budget.status==='EXCEEDED'?'#c6744e':budget.status==='NEAR_LIMIT'?'#b6974a':'#27856c'"/><div class="budget-scale"><span>0%</span><span>80% · 提醒线</span><span>100%</span></div><div class="budget-status" :class="budget.status"><AppIcon :name="budget.status==='NORMAL'?'CircleCheck':'Warning'" :size="24"/><div><h3>{{budgetText(budget)}}</h3><p>{{Number(budget.remaining)>=0?'还可使用':'已经超出'}} {{money(Math.abs(Number(budget.remaining)))}}</p></div></div></template><div v-else class="no-budget"><AppIcon name="Wallet" :size="48"/><h3>给开销一个清晰的范围</h3><p>本月已支出 {{money(budget.spent)}}，设置预算后可查看使用进度。</p></div></section><div class="budget-tips"><h3>预算提醒怎么计算？</h3><div><span>01</span><p>仅统计所选月份的支出，收入不抵减预算使用额。</p></div><div><span>02</span><p>使用率达到80%时提醒，达到100%时显示预算已用完或超出。</p></div><div><span>03</span><p>修改、删除账单后重新进入页面，即可查看更新的预算情况。</p></div></div></StateBox><el-dialog v-model="dialog" title="设置月度预算" width="430px" :close-on-click-modal="false"><p class="muted">{{month}} 的支出计划</p><el-form ref="formRef" :model="form" label-position="top" @submit.prevent="save"><el-form-item label="预算金额（元）" prop="amount" :rules="[moneyRule]"><el-input v-model="form.amount" inputmode="decimal" placeholder="例如：2000.00" maxlength="13"/></el-form-item><div class="dialog-footer"><el-button @click="dialog=false">取消</el-button><el-button type="primary" native-type="submit" :loading="busy">保存预算</el-button></div></el-form></el-dialog></template>
